import React, { useState } from 'react';
import Navbar from '../components/Navbar';
import { FaPaperPlane, FaUserSecret, FaLock, FaHeart, FaShieldAlt } from 'react-icons/fa';

function AnonymousChat() {
  const [messages, setMessages] = useState([
    { id: 1, text: "Welcome to Anonymous Support Space. You can share anything here. Your identity is completely hidden.", isUser: false, time: new Date().toLocaleTimeString() }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);

  const getAIResponse = (message) => {
    const msg = message.toLowerCase();
    if (msg.includes('sad') || msg.includes('depressed')) {
      return "I hear you. It's okay to feel sad. You're not alone in this. Would you like to talk about what's bothering you?";
    }
    if (msg.includes('stress') || msg.includes('overwhelm')) {
      return "That sounds really challenging. Remember to breathe. Let's take it one step at a time. What's one small thing you can do right now?";
    }
    if (msg.includes('exam') || msg.includes('study')) {
      return "Academic pressure is real. Break your study into small chunks. You've got this! 📚";
    }
    if (msg.includes('friend') || msg.includes('lonely')) {
      return "Feeling lonely is tough. Remember that many people care about you. Would you like to join a study group or club?";
    }
    return "Thank you for sharing. Your feelings are valid. I'm here to listen anonymously. What would help you feel better right now?";
  };

  const sendMessage = () => {
    if (!input.trim()) return;
    
    const userMessage = { id: Date.now(), text: input, isUser: true, time: new Date().toLocaleTimeString() };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);
    
    setTimeout(() => {
      const aiResponse = { id: Date.now() + 1, text: getAIResponse(input), isUser: false, time: new Date().toLocaleTimeString() };
      setMessages(prev => [...prev, aiResponse]);
      setIsTyping(false);
    }, 1000);
  };

  return (
    <div style={styles.container}>
      <Navbar />
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}><FaUserSecret /> Anonymous Support Space</h1>
          <p style={styles.subtitle}>Share freely. Your identity is completely hidden.</p>
        </div>

        <div style={styles.privacyCard}>
          <FaLock color="#2ecc71" size={20} />
          <span>🔒 100% Anonymous - No personal information is stored</span>
        </div>

        <div style={styles.chatContainer}>
          <div style={styles.messagesArea}>
            {messages.map(msg => (
              <div key={msg.id} style={{...styles.message, justifyContent: msg.isUser ? 'flex-end' : 'flex-start'}}>
                <div style={{...styles.messageBubble, background: msg.isUser ? '#667eea' : '#f0f0f0', color: msg.isUser ? 'white' : '#333'}}>
                  <p style={styles.messageText}>{msg.text}</p>
                  <span style={styles.messageTime}>{msg.time}</span>
                </div>
              </div>
            ))}
            {isTyping && (
              <div style={styles.typingIndicator}>
                <div style={styles.typingDot}></div>
                <div style={styles.typingDot}></div>
                <div style={styles.typingDot}></div>
              </div>
            )}
          </div>
          
          <div style={styles.inputArea}>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
              placeholder="Type your message anonymously..."
              style={styles.input}
            />
            <button onClick={sendMessage} style={styles.sendBtn}>
              <FaPaperPlane />
            </button>
          </div>
        </div>

        <div style={styles.resourcesCard}>
          <h4><FaHeart /> Anonymous Resources</h4>
          <p>📞 Crisis Helpline: 988 (24/7)</p>
          <p>💬 Text HOME to 741741</p>
          <p>🌐 Online Counseling: BetterHelp, 7 Cups</p>
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: { minHeight: '100vh', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' },
  content: { maxWidth: '800px', margin: '0 auto', padding: '20px', paddingTop: '80px' },
  header: { textAlign: 'center', marginBottom: '20px', color: 'white' },
  title: { fontSize: '28px', marginBottom: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '10px' },
  subtitle: { fontSize: '14px', opacity: 0.9 },
  privacyCard: { background: 'rgba(255,255,255,0.95)', borderRadius: '12px', padding: '12px', marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '10px', fontSize: '14px', fontWeight: '500' },
  chatContainer: { background: 'white', borderRadius: '20px', height: '500px', display: 'flex', flexDirection: 'column', overflow: 'hidden' },
  messagesArea: { flex: 1, overflowY: 'auto', padding: '20px', display: 'flex', flexDirection: 'column', gap: '12px' },
  message: { display: 'flex' },
  messageBubble: { maxWidth: '70%', padding: '10px 15px', borderRadius: '20px' },
  messageText: { margin: 0, fontSize: '14px' },
  messageTime: { fontSize: '10px', opacity: 0.6, display: 'block', marginTop: '5px' },
  typingIndicator: { display: 'flex', gap: '5px', padding: '10px 15px', background: '#f0f0f0', borderRadius: '20px', width: '50px' },
  typingDot: { width: '8px', height: '8px', background: '#999', borderRadius: '50%', animation: 'bounce 1s infinite' },
  inputArea: { display: 'flex', padding: '15px', gap: '10px', borderTop: '1px solid #e0e0e0' },
  input: { flex: 1, padding: '12px', border: '2px solid #e0e0e0', borderRadius: '25px', outline: 'none' },
  sendBtn: { background: '#667eea', color: 'white', border: 'none', width: '45px', height: '45px', borderRadius: '50%', cursor: 'pointer' },
  resourcesCard: { marginTop: '20px', background: 'white', borderRadius: '15px', padding: '15px' },
};

export default AnonymousChat;
